M = {'m00': 10, 'm10': 50, 'm01': 70}
result = centroid_from_moments(M)
assert result == (5.0, 7.0), f'oczekiwano (5.0, 7.0), otrzymano {result}'

data.solution:
def centroid_from_moments(M):
    if M['m00'] == 0:
        return None
    cx = M['m10'] / M['m00']
    cy = M['m01'] / M['m00']
    return (cx, cy)
